<?php if($report['external']):?><h3 class="section-title">Externe Stellen</h3><div class="timeline-list"><?php foreach($report['external'] as $x):?><div class="timeline-item"><strong><?= e($x['organization_master_name']??$x['organization_name']??'–') ?></strong><small class="table-sub"><?= e($x['contact_name']??'') ?> · <?= e(format_datetime($x['notified_at'])) ?> · <?= e($x['reference_number']??'') ?></small><div><?= e($x['feedback']??'') ?></div></div><?php endforeach;?></div><?php endif;?>
