</div>

<?php if($report['revision_requests']):?><div class="panel"><div class="panel-header"><div><h2>Nachforderungen</h2><p>Einzelne Prüfpunkte aus der Leitungsprüfung.</p></div></div><div class="timeline-list"><?php foreach($report['revision_requests'] as $rr):?><div class="timeline-item"><strong><?= e($rr['request_text']) ?></strong><small class="table-sub"><?= e($rr['creator_name']??'') ?> · <?= e(format_datetime($rr['created_at'])) ?> · <?= $rr['status']==='done'?'Erledigt':'Offen' ?></small><?php if($rr['status']==='open'&&(int)$report['created_by']===(int)\WKS\Core\Auth::id()):?><form method="post" action="<?= e(url('special-reports/'.$report['id'].'/revision/'.$rr['id'].'/done')) ?>"><?= csrf_field() ?><button class="button secondary compact" type="submit">Als erledigt markieren</button></form><?php endif;?></div><?php endforeach;?></div></div><?php endif;?>

<?php if(in_array($report['status'],['draft','in_progress','revision_required'],true)&&can('special_reports.close')):?><div class="panel"><div class="panel-header"><div><h2>Bericht abschließen</h2><p>Mit dem Abschluss bestätigt der Ersteller den Bericht digital. Danach ist er bis zu einer Nachbearbeitungsanforderung gesperrt.</p></div></div><form method="post" action="<?= e(url('special-reports/'.$report['id'].'/complete')) ?>"><?= csrf_field() ?><button class="button primary" type="submit">Bericht digital bestätigen & abschließen</button></form></div><?php endif;?>

<?php if($report['status']==='completed'&&(can('special_reports.review')||can('special_reports.request_revision'))):?><div class="two-col"><?php if(can('special_reports.request_revision')):?><div class="panel"><h2>Nachbearbeitung anfordern</h2><form method="post" action="<?= e(url('special-reports/'.$report['id'].'/review/request')) ?>" class="stack-form"><input type="hidden" name="_token" value="<?= e(\WKS\Core\Csrf::token()) ?>"><div id="revision-repeat" class="repeat-list"><div data-repeat-row><label>Nachforderung 1<textarea name="requests[0]" required></textarea></label></div><template><div data-repeat-row><label>Weitere Nachforderung<textarea name="requests[__INDEX__]" required></textarea></label><button type="button" class="button ghost compact" data-repeat-remove>Entfernen</button></div></template></div><button type="button" class="button secondary" data-repeat-add="#revision-repeat">+ Nachforderung</button><label>Allgemeiner Prüfvermerk<textarea name="review_note"></textarea></label><button class="button danger" type="submit">Nachbearbeitung anfordern</button></form></div><?php endif;?><?php if(can('special_reports.review')):?><div class="panel"><h2>Leitungsprüfung abschließen</h2><form method="post" action="<?= e(url('special-reports/'.$report['id'].'/review/approve')) ?>" class="stack-form"><?= csrf_field() ?><label>Prüfvermerk<textarea name="review_note"></textarea></label><button class="button primary" type="submit">Prüfung digital bestätigen</button></form></div><?php endif;?></div><?php endif;?>

<?php if($report['status']==='reviewed'):?><div class="panel"><div class="panel-header"><div><h2>Versionen</h2><p>Geprüfte und spätere Fassungen bleiben unveränderlich nachvollziehbar.</p></div></div><div class="timeline-list"><?php foreach($report['versions'] as $v):?><div class="timeline-item"><strong>Version <?= (int)$v['version_number'] ?></strong><small class="table-sub"><?= e(format_datetime($v['created_at'])) ?> · <?= e($v['user_name']??'') ?></small></div><?php endforeach;?></div></div><?php if(can('special_reports.close')):?><div class="panel"><h2>Dokumentierter Nachtrag</h2><form method="post" action="<?= e(url('special-reports/'.$report['id'].'/addendum')) ?>" class="stack-form"><?= csrf_field() ?><label>Änderungsgrund*<input name="reason" required></label><label>Sachverhalt*<textarea name="facts" rows="7" required><?= e($report['facts']) ?></textarea></label><label>Maßnahmen<textarea name="measures_text" rows="3"><?= e($report['measures_text']??'') ?></textarea></label><label>Ergebnis<textarea name="result_text" rows="3"><?= e($report['result_text']??'') ?></textarea></label><button class="button primary" type="submit">Nachtrag als neue Version speichern</button></form></div><?php endif;?><?php endif;?>

